const HTIMG={g1:"https://cdn.jsdelivr.net/gh/cyberni1/Krabi-Resort@8cff35258905f475cf8ea289d6da717b327cbdc0/g1.webp",g2:"https://cdn.jsdelivr.net/gh/cyberni1/Krabi-Resort@8cff35258905f475cf8ea289d6da717b327cbdc0/g2.webp",g3:"https://cdn.jsdelivr.net/gh/cyberni1/Krabi-Resort@8cff35258905f475cf8ea289d6da717b327cbdc0/g3.webp",show:"https://cdn.jsdelivr.net/gh/cyberni1/Krabi-Resort@8cff35258905f475cf8ea289d6da717b327cbdc0/show.webp"};
function renderHT(){
  const d=HT[LANG]||HT.en;
  $("#ht-sub").textContent=d.sub;
  const sec=([h,ps,img])=>`<h3>${h}</h3>${ps.map(p=>`<p>${p}</p>`).join("")}${img?`<figure class="ht-fig"><img src="${HTIMG[img]}" alt="Atomix 705 HT" loading="lazy"></figure>`:""}`;
  $("#ht-body").innerHTML=`<p class="lead">${d.lead}</p>${d.intro.map(p=>`<p>${p}</p>`).join("")}
    ${d.secs.map(sec).join("")}
    <p style="color:var(--hull);font-weight:600;margin-top:2rem">${d.usesH}</p><ul class="ht-uses">${d.uses.map(u=>`<li>${u}</li>`).join("")}</ul><p>${d.usesP}</p>
    ${d.secs2.map(sec).join("")}
    <h3>${d.benH}</h3><ul class="ht-ben">${d.ben.map(b=>`<li>${b}</li>`).join("")}</ul>
    <h3>${d.cfgH}</h3>${d.cfg.map(p=>`<p>${p}</p>`).join("")}
    <h3>${d.techH}</h3><div class="tbl-wrap" style="margin-top:1.2rem"><table style="min-width:0"><tbody>${d.tech.map(([k,v])=>`<tr><th scope="row">${k}</th><td style="white-space:normal">${v}</td></tr>`).join("")}</tbody></table></div>
    <p class="price-note">${d.note}</p>
    <div class="ht-cta"><h3 style="margin:0">${d.ctaH}</h3><p>${d.cta}</p><p class="slogan">${d.slogan}</p>
      <div class="row"><a class="btn btn-go" href="#quote" data-htq>${d.btnQuote}</a><a class="btn btn-ghost" href="#fleet" data-pick="705ht">${d.btnCfg}</a></div></div>`;
  $("#ht-body").querySelectorAll("[data-pick]").forEach(a=>a.addEventListener("click",()=>select("705ht",false)));
  $("#ht-body").querySelector("[data-htq]").addEventListener("click",()=>{select("705ht",false);});
}
