let exCat="all";
const exCats=["all","p","s","m","h","2s","acc"];
function specOf(e,re){const s=e.specs.find(([k])=>re.test(k));return s?s[1]:"–";}
function renderExtras(){
  $("#ex-filters").innerHTML=exCats.map(c=>`<button type="button" data-cat="${c}" aria-pressed="${c===exCat}">${t("f."+c)}</button>`).join("");
  $("#ex-filters").querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{exCat=b.dataset.cat;renderExtras();}));
  const list=ENG.filter(e=>exCat==="all"||e.cat===exCat);
  $("#ex-count").textContent=fill(t("ex.count"),{n:list.length});
  $("#ex-grid").innerHTML=list.map(e=>{
    const img=e.img?`<img src="${SUZIMG[e.img]}" alt="Suzuki ${e.name}" loading="lazy">`:`<span class="noimg">${e.name.split(" ")[0]}</span>`;
    const hp=e.hp?`<span class="hp">${dec(e.hp)} ${LANG==="de"?"PS":LANG==="ru"?"л.с.":LANG==="zh"?"马力":LANG==="th"?"แรงม้า":"hp"}</span>`:"";
    const ds=e.cat!=="acc"?`<p class="ds">${t("d."+e.cat)}</p>`:"";
    const keys=e.specs.length?`<div class="eng-k"><span>${t("ex.weight")}<b>${specOf(e,/^weight/i)}</b></span><span>${t("ex.kw")}<b>${specOf(e,/^max/i)}${/^max/i.test((e.specs.find(([k])=>/^max/i.test(k))||[""])[0])?" kW":""}</b></span><span>${t("ex.disp")}<b>${specOf(e,/displacement/i)}</b></span></div>
      <details><summary>${t("ex.specs")}</summary><dl>${e.specs.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join("")}</dl></details>`:"";
    return `<article class="eng"><div class="eng-img" style="background:${e.bg||"#eeeeee"}">${img}${e.pk?`<span class="tag">${t("ex.inpk")}</span>`:""}</div>
      <div class="eng-b"><h3>${e.name}</h3>${hp}${ds}<div class="pr"><small>${t("ex.from")}</small>${fmt(e.price)} ${cur$()}</div>${keys}
      <button class="mini" type="button" data-ask="${e.name}" data-price="${e.price}">${t("ex.ask")}</button></div></article>`;
  }).join("");
  $("#ex-grid").querySelectorAll("[data-ask]").forEach(b=>b.addEventListener("click",()=>{
    $("#q-msg").value=fill(t("ex.askmsg"),{name:"Suzuki "+b.dataset.ask,price:fmt(+b.dataset.price)});
    location.hash="#quote";
  }));
}
const PAGES=["extras","705ht"];
const pathPage=()=>{const m=location.pathname.match(/\/(extras|705ht)\/?$/);return m?m[1]:null;};
const basePath=()=>location.pathname.replace(/\/(extras|705ht)\/?$/,"/")||"/";
function goHome(e){
  if(e)e.preventDefault();
  history.pushState(null,"",basePath());
  document.body.dataset.view="home";
  window.scrollTo({top:0,behavior:"smooth"});
}
document.querySelectorAll(".brand,.ex-back:not(.ht-more),.go-home").forEach(a=>a.addEventListener("click",goHome));
function route(){
  const h=location.hash.slice(1);
  if(pathPage()&&h&&!PAGES.includes(h)){history.replaceState(null,"",basePath()+location.hash);}
  const v=PAGES.includes(h)?h:(pathPage()&&!h?pathPage():"home");
  const was=document.body.dataset.view;
  document.body.dataset.view=v;
  if(v!=="home"){if(was!==v)window.scrollTo(0,0);}
  else if(was&&was!=="home"){requestAnimationFrame(()=>{const el=h&&document.getElementById(h);el?el.scrollIntoView():window.scrollTo(0,0);});}
}
addEventListener("hashchange",route);
addEventListener("popstate",route);

/* opening hours (Phuket time) */
const HOURS={1:[9,17],2:[9,17],3:[9,17],4:[9,17],5:[9,17]};
function renderHours(){
  const now=new Date(new Date().toLocaleString("en-US",{timeZone:"Asia/Bangkok"}));
  const today=now.getDay(),hr=now.getHours()+now.getMinutes()/60;
  const loc=LANG==="zh"?"zh-CN":LANG;
  const dayName=d=>new Intl.DateTimeFormat(loc,{weekday:"long"}).format(new Date(2024,0,7+d));
  $("#hours").innerHTML=[1,2,3,4,5,6,0].map(d=>{const h=HOURS[d],c=d===today?' class="today"':"";return `<span${c}>${dayName(d)}</span><span${c}>${h?`${String(h[0]).padStart(2,"0")}:00–${h[1]}:00`:t("h.closed")}</span>`;}).join("");
  const open=HOURS[today]&&hr>=HOURS[today][0]&&hr<HOURS[today][1];
  const p=$("#open-pill");p.textContent=open?t("h.open"):t("h.shut");p.className="open-pill "+(open?"on":"off");
}
setInterval(()=>{try{renderHours()}catch(e){}},60000);
